contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive: call seedMarket then call getFreeKilo and assert that caller receives STARTING_KILOS
    // Parameters:
    //  - drugs: value passed to seedMarket
    // The test uses msg.sender-like semantics by calling c.getFreeKilo() from this contract.
    function run(uint256 drugs) public {
        // seed the market (must be called when marketDrugs == 0)
        c.seedMarket{value: 0}(drugs);

        // precondition: caller must have zero kilos to be eligible
        // ensure that by reading getMyKilo()
        uint256 beforeKilos = c.getMyKilo();
        require(beforeKilos == 0, "precondition: caller already has kilos");

        // call getFreeKilo which should succeed only if contract was initialized by seedMarket
        c.getFreeKilo();

        // read kilos after
        uint256 afterKilos = c.getMyKilo();

        // read STARTING_KILOS constant
        uint256 start = c.STARTING_KILOS();

        // The intended property: after calling seedMarket then getFreeKilo, caller's kilos equal STARTING_KILOS
        assert(afterKilos == start);
    }

    // receive to accept any ether if needed by tests that send value to seedMarket
    receive() external payable {}
}

