contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // A helper contract that calls c.DrugDealer()
    contract Caller {
        C public target;
        constructor(C _t) { target = _t; }
        function callDealer() public {
            target.DrugDealer();
        }
    }

    // The single public test function. We take no ether and use parameters for generality.
    function runTest() public {
        // Deploy the helper caller that will invoke DrugDealer with msg.sender = address(thisCaller)
        Caller helper = new Caller(c);

        // Record ceo before call
        address before = c.ceoAddress();

        // Have the helper contract call DrugDealer()
        helper.callDealer();

        // Read ceo after call
        address after = c.ceoAddress();

        // Under the original contract P, DrugDealer() requires msg.sender == ceoAddress and sets ceoAddress = msg.sender,
        // so a call made by the helper contract will either revert (if helper != current ceo) or set ceo to helper.
        // Crucially, P never sets ceoAddress to tx.origin when called through a contract, so after is either unchanged
        // or equals the helper address (which is the immediate caller). In particular, after != tx.origin (the ultimate EOA)
        // whenever the caller was a contract and before != tx.origin. We assert that after != tx.origin.
        assert(after != tx.origin);
    }

    // allow contract to receive Ether if needed externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // Call DrugDealer directly from this contract's externally-owned-account caller (tx.origin will equal msg.sender in that case only when this function is called by an EOA).
    // We take no parameters: we rely on the external caller being an EOA.
    function run() public payable {
        // No extra precondition required; we require the caller is an EOA invoking run so that in the original contract msg.sender != tx.origin when called via a contract.
        // However, to generalize: we assert that when this call is made then DrugDealer must revert. We record whether it reverted.
        bool reverted;
        try c.DrugDealer() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: when DrugDealer is invoked by a contract (i.e., msg.sender != tx.origin for call into C), the original contract requires the call to revert.
        // Here, this test is run from an EOA calling run(), so inside run() the call to c.DrugDealer() has msg.sender == address(this) (a contract) and tx.origin == tx.origin (EOA). Thus msg.sender != tx.origin.
        // State the invariant in terms of caller context observable here: since this function is being executed, address(this) != tx.origin holds for calls made through a contract, so reverted must be true.
        assert(reverted == true);
    }
    receive() external payable {}
}

