contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address that will act as the CEO caller
    function testFuzz_property(address possibleCeo) public {
        // keep address non-zero and distinct from contract address to be an EOA-like actor
        vm.assume(possibleCeo != address(0));
        vm.assume(possibleCeo != address(c));

        // arrange: set contract into initialized state so other require checks don't interfere
        // seedMarket requires marketDrugs==0; call it from deployer (setUp caller) with some drugs
        c.seedMarket{value: 0}(1);

        // We need the ceoAddress of the contract to be possibleCeo for this test to be meaningful.
        // The reference contract sets ceoAddress in declaration to a specific hardcoded address in source.
        // To make possibleCeo the current ceo, we impersonate that hardcoded address to call DrugDealer only if it equals possibleCeo.
        // If not equal, we instead expect that a call from the hardcoded CEO (the original address in source) can make itself the caller,
        // and we must fuzz so that possibleCeo equals that CEO in some runs. To keep the test universal for all possibleCeo,
        // we first fetch the current ceoAddress and require the fuzzer to supply that exact address as possibleCeo.

        address currentCeo = c.ceoAddress();
        // constrain the fuzzed input to match the contract's current ceoAddress
        vm.assume(possibleCeo == currentCeo);

        // Act: have the ceo call DrugDealer()
        vm.prank(possibleCeo);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: after the call, in the reference implementation the ceoAddress must still equal the caller
        // i.e., c.ceoAddress() == possibleCeo
        assertTrue(ok && c.ceoAddress() == possibleCeo);
    }
}
